package ai.taskforge.domain;
import jakarta.persistence.*; import java.time.*; import java.util.*;
@Entity @Table(name="notifications",indexes=@Index(name="idx_notification_user_read",columnList="recipient_id,read")) public class Notification { @Id @GeneratedValue private UUID id; @ManyToOne(optional=false) @JoinColumn(name="recipient_id") private AppUser recipient; @Column(nullable=false) private String type; @Column(nullable=false,length=1000) private String message; private boolean read=false; private Instant createdAt=Instant.now(); protected Notification(){} public Notification(AppUser r,String t,String m){recipient=r;type=t;message=m;} public UUID getId(){return id;} public String getType(){return type;} public String getMessage(){return message;} public boolean isRead(){return read;} public Instant getCreatedAt(){return createdAt;} public void markRead(){read=true;} }
